class RingScreen extends StatefulWidget{const RingScreen({super.key});@override State<RingScreen> createState()=>_RingScreenState();}
class _RingScreenState extends State<RingScreen>{final clock=RingClockController();final audio=RingAudioService();final blue=List<bool>.filled(4,false),red=List<bool>.filled(4,false);bool soundOn=true;double volume=.65;@override void initState(){super.initState();clock.onCue=_cue;clock.addListener(_refresh);_enter();}Future<void> _enter() async {await SystemChrome.setPreferredOrientations([DeviceOrientation.landscapeLeft,DeviceOrientation.landscapeRight]);await WakelockPlus.enable();}void _refresh(){if(mounted)setState((){});}Future<void> _cue(LightPhase p)async{audio.enabled=soundOn;audio.volume=volume;if([LightPhase.red1,LightPhase.red2,LightPhase.red3].contains(p)){await audio.redCue();}else if(p==LightPhase.green){await audio.greenCue();}}void _reset(){setState((){for(var i=0;i<4;i++){blue[i]=false;red[i]=false;}});clock.reset();}@override void dispose(){clock.removeListener(_refresh);clock.dispose();audio.dispose();WakelockPlus.disable();SystemChrome.setPreferredOrientations([DeviceOrientation.portraitUp]);super.dispose();}
@override Widget build(BuildContext context)=>Scaffold(body:SafeArea(child:LayoutBuilder(builder:(context,size){final compact=size.maxHeight<520;final lamp=compact?68.0:82.0;return Column(children:[_top(context),Expanded(child:Padding(padding:const EdgeInsets.fromLTRB(14,4,14,8),child:Row(children:[Expanded(flex:3,child:_faults('BLUE',AppTheme.blueLane,blue)),Expanded(flex:5,child:_tower(lamp,compact)),Expanded(flex:3,child:_faults('RED',AppTheme.redLane,red))]))),_controls(compact)]);})));Widget _top(BuildContext c)=>Padding(padding:const EdgeInsets.fromLTRB(12,6,12,0),child:Row(children:[IconButton(onPressed:()=>Navigator.of(c).pop(),icon:const Icon(Icons.close)),const Text('LOCAL RING · REV 0.1',style:TextStyle(color:AppTheme.textMuted,fontWeight:FontWeight.w800,letterSpacing:.9)),const Spacer(),IconButton(onPressed:()=>setState(()=>soundOn=!soundOn),icon:Icon(soundOn?Icons.volume_up_rounded:Icons.volume_off_rounded,color:soundOn?AppTheme.gold:Colors.white38)),SizedBox(width:130,child:Slider(value:volume,min:0,max:1,onChanged:soundOn?(v)=>setState(()=>volume=v):null))]));Widget _faults(String title,Color color,List<bool> vals)=>Column(mainAxisAlignment:MainAxisAlignment.center,children:[Text('$title LANE',style:TextStyle(color:color,fontWeight:FontWeight.w900,letterSpacing:1.4)),const SizedBox(height:12),for(var i=0;i<4;i++)...[FaultButton(dogNumber:i+1,laneColor:color,active:vals[i],onTap:()=>setState(()=>vals[i]=!vals[i])),if(i!=3)const SizedBox(height:8)]]);Widget _tower(double lamp,bool compact)=>Column(mainAxisAlignment:MainAxisAlignment.center,children:[Container(padding:EdgeInsets.symmetric(horizontal:compact?18:24,vertical:compact?10:18),decoration:BoxDecoration(color:const Color(0xFF0E131B),borderRadius:BorderRadius.circular(32),border:Border.all(color:AppTheme.border,width:2)),child:Column(children:[FlyballLamp(color:const Color(0xFFE54242),active:clock.phase==LightPhase.red1,size:lamp),SizedBox(height:compact?5:10),FlyballLamp(color:const Color(0xFFE54242),active:clock.phase==LightPhase.red2,size:lamp),SizedBox(height:compact?5:10),FlyballLamp(color:const Color(0xFFE54242),active:clock.phase==LightPhase.red3,size:lamp),SizedBox(height:compact?5:10),FlyballLamp(color:AppTheme.green,active:clock.phase==LightPhase.green,size:lamp)])),SizedBox(height:compact?8:14),FittedBox(child:Text(clock.display,style:TextStyle(fontSize:compact?54:68,fontWeight:FontWeight.w900,fontFeatures:const [FontFeature.tabularFigures()],letterSpacing:2,color:clock.state==RingClockState.stopped?AppTheme.gold:Colors.white)))]);Widget _controls(bool compact){final running=clock.state==RingClockState.countdown||clock.state==RingClockState.racing;return Container(color:const Color(0xFF0C1016),padding:EdgeInsets.fromLTRB(16,compact?7:12,16,compact?8:14),child:Row(children:[Expanded(child:_btn('GO',Icons.play_arrow_rounded,AppTheme.green,Colors.black,running?null:clock.go)),const SizedBox(width:12),Expanded(child:_btn('STOP',Icons.stop_rounded,AppTheme.redLane,Colors.white,running?clock.stop:null)),const SizedBox(width:12),Expanded(child:_btn('RESET',Icons.refresh_rounded,AppTheme.surface2,Colors.white,_reset))]));}Widget _btn(String label,IconData icon,Color color,Color fg,VoidCallback? cb)=>FilledButton.icon(onPressed:cb,icon:Icon(icon,size:30),label:Text(label,style:const TextStyle(fontSize:20,fontWeight:FontWeight.w900)),style:FilledButton.styleFrom(backgroundColor:color,foregroundColor:fg,disabledBackgroundColor:color.withValues(alpha:.18),disabledForegroundColor:fg.withValues(alpha:.35),padding:const EdgeInsets.symmetric(vertical:14)));
}
